// Extrae los parámetros de entrada del webhook de Next.js o del mock
const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    clerk_user_id: String(body.clerk_user_id || 'user_clerk_demo_camila').trim(),
    imagen_path: String(body.imagen_path || 'user_clerk_demo_camila/semana_2_estudio_ojos.jpg').trim(),
    notas_usuaria: String(body.notas_usuaria || 'Práctica de rostro 3/4').trim(),
    fecha: $now.setZone('America/La_Paz').toFormat('yyyy-MM-dd HH:mm')
  }
}];

// Genera la URL firmada simulada/real y carga la memoria de hasta 3 obras previas
// para garantizar que la demo corra en vivo incluso sin red externa.
const entrada = $input.first().json;

// Historial previo de Camila (Semana 1)
const historialObras = [
  {
    semana: 1,
    fecha: '2026-11-14',
    notas: 'Primer intento en 3/4. Siento que el ojo derecho quedó caído y el sombreado plano.',
    aciertos_previos: ['Buena intención en la curva mandibular', 'Trazo suelto en cabello'],
    consejo_previo: 'Traza un eje horizontal de guía antes de dibujar el segundo ojo',
    reto_previo: 'Dibuja 3 pares de ojos alineados con una línea de horizonte.'
  }
];

const tieneObrasPrevias = historialObras.length > 0;

// Prompt enriquecido con memoria histórica
const promptMemoria = `
ARTISTA: ${entrada.clerk_user_id}
NOTAS DE LA ARTISTA HOY:
"${entrada.notas_usuaria}"

MEMORIA HISTÓRICA DE OBRAS PREVIAS (${historialObras.length} obras registradas):
${historialObras.map(o => `- Obra previa (${o.fecha}): Notas: "${o.notas}" | Reto asignado: "${o.reto_previo}"`).join('\n')}

INSTRUCCIÓN DE MUSA (Mentora Artística):
1. Evalúa los aciertos técnicos de la entrega actual.
2. Brinda 1 consejo técnico práctico y específico para su siguiente sesión.
3. Si tiene obras previas, compara explícitamente cómo evolucionó respecto al reto anterior.
4. Propone el siguiente reto creativo alcanzable en 3 a 5 días.
5. Agrega un mensaje cálido y motivador que premie su constancia.` ;

return [{
  json: {
    ...entrada,
    signed_url: `https://TU-PROYECTO.supabase.co/storage/v1/object/sign/obras/${entrada.imagen_path}?token=demo_token_123`,
    historial_previo: historialObras,
    tiene_obras_previas: tieneObrasPrevias,
    prompt_gemini: promptMemoria
  }
}];

// Estructura el contrato exacto de feedback_ia para Supabase y Next.js
const item = $input.first();
const ia = item.json.output || {};
const entrada = $('Firmar URL & Memoria Histórica').first().json;

const feedback = {
  aciertos: Array.isArray(ia.aciertos) ? ia.aciertos : ["Alineación precisa del eje de los ojos en 3/4", "Mayor profundidad con grafito 4B en el pómulo"],
  consejo_tecnico: ia.consejo_tecnico || "Suaviza la transición entre la sombra profunda del pómulo y la luz alta usando un difumino o lápiz 2B.",
  comparacion: entrada.tiene_obras_previas
    ? (ia.comparacion || "Respecto a tu primer boceto, la simetría ocular mejoró radicalmente gracias al uso de las líneas guía de horizonte.")
    : null,
  siguiente_reto: ia.siguiente_reto || "Dibuja un nuevo estudio de 3/4 enfocándote en capturar 3 niveles de brillo especular (luz pura, medio tono y sombra).",
  mensaje: ia.mensaje || "¡Gran avance, Camila! El salto técnico de esta semana demuestra que la constancia transforma el talento."
};

return [{
  json: {
    clerk_user_id: entrada.clerk_user_id,
    imagen_path: entrada.imagen_path,
    notas_usuaria: entrada.notas_usuaria,
    feedback_ia: feedback
  }
}];
